import React from "react";
import { CHAPTERS_REGISTRY } from "@/lib/chapters";

interface FilterPanelProps {
  activeFilters: {
    grade: string;
    subject: string;
    chapterId: string;
    difficulty: string;
    trackType: string;
    preparationLevel: 'FOUNDATION' | 'JEE_MAIN_ADVANCED';
  };
  onUpdateFilters: (updated: any) => void;
  onGenerate: () => void;
  hideAnswerKeyUntilSubmit: boolean;
  setHideAnswerKeyUntilSubmit: React.Dispatch<React.SetStateAction<boolean>>;
  clearActiveToast: () => void;
}

export default function FilterPanel({
  activeFilters,
  onUpdateFilters,
  onGenerate,
  hideAnswerKeyUntilSubmit,
  setHideAnswerKeyUntilSubmit,
  clearActiveToast
}: FilterPanelProps) {
  
  const filteredChaptersList = CHAPTERS_REGISTRY.filter((ch) => {
    const cleanActiveSubject = activeFilters.subject.replace(/[^a-zA-Z]/g, "").trim().toLowerCase();
    const cleanChSubject = ch.subject.replace(/[^a-zA-Z]/g, "").trim().toLowerCase();

    return ch.grade === activeFilters.grade && cleanChSubject === cleanActiveSubject && ch.category === 'JEE_PREP';
  });

  return (
    <div className="bg-white border border-zinc-200 p-6 rounded-2xl shadow-sm space-y-5 text-left">
      <div>
        <span className="text-[10px] font-mono font-bold tracking-widest text-zinc-400 uppercase">
          Config Parameters Panel
        </span>
        <h2 className="text-xl font-black text-zinc-900 mt-0.5">Generate Worksheet</h2>
      </div>

      {/* 🔒 SECURITY TOGGLE CONTROLS */}
      <div className="flex items-center space-x-3 bg-zinc-50 border p-3 rounded-xl">
        <input 
          type="checkbox" 
          id="hide-key-toggle-panel"
          checked={hideAnswerKeyUntilSubmit} 
          onChange={(e) => setHideAnswerKeyUntilSubmit(e.target.checked)}
          className="w-4 h-4 rounded text-zinc-900 accent-zinc-900 cursor-pointer"
        />
        <label htmlFor="hide-key-toggle-panel" className="text-xs font-bold text-zinc-700 uppercase tracking-wide cursor-pointer select-none">
          🔒 Hide Answer Key Until Submitted
        </label>
      </div>

      {/* 🧭 STEP 1: PREPARATION LEVEL TOGGLE PORTAL */}
      <div className="space-y-1.5">
        <label className="block text-[11px] font-mono font-bold text-zinc-400 uppercase tracking-wider">Preparation Level</label>
        <div className="grid grid-cols-2 gap-2 text-xs font-bold">
          <button
            type="button"
            onClick={() => onUpdateFilters({ ...activeFilters, preparationLevel: 'FOUNDATION', grade: '8', subject: 'Biology', chapterId: '' })}
            className={`p-2.5 rounded-xl border text-center transition ${activeFilters.preparationLevel === 'FOUNDATION' ? 'border-zinc-900 bg-zinc-900 text-white shadow' : 'bg-white text-zinc-600 hover:bg-zinc-50'}`}
          >
            Foundation Track
          </button>
          <button
            type="button"
            onClick={() => onUpdateFilters({ ...activeFilters, preparationLevel: 'JEE_MAIN_ADVANCED', grade: '12', subject: 'Physics', chapterId: '' })}
            className={`p-2.5 rounded-xl border text-center transition ${activeFilters.preparationLevel === 'JEE_MAIN_ADVANCED' ? 'border-zinc-900 bg-zinc-900 text-white shadow' : 'bg-white text-zinc-600 hover:bg-zinc-50'}`}
          >
            JEE Main / Advanced
          </button>
        </div>
      </div>

      {/* 📊 STEP 2: MULTI-GRADE TARGET SELECTOR */}
      <div className="space-y-1.5">
        <label className="block text-[11px] font-mono font-bold text-zinc-400 uppercase tracking-wider">Target Grade Level</label>
        <select
          value={activeFilters.grade}
          onChange={(e) => onUpdateFilters({ ...activeFilters, grade: e.target.value, chapterId: '' })}
          className="w-full border border-zinc-200 p-2.5 rounded-xl bg-zinc-50/50 text-sm font-semibold text-zinc-800 focus:outline-none focus:border-zinc-400"
        >
          {activeFilters.preparationLevel === 'FOUNDATION' ? (
            <>
              <option value="8">Grade 8 (Foundational)</option>
              <option value="9">Grade 9 (Foundational)</option>
              <option value="10">Grade 10 (Foundational)</option>
            </>
          ) : (
            <>
              <option value="11">Class 11 (JEE Prep)</option>
              <option value="12">Class 12 (JEE Prep)</option>
            </>
          )}
        </select>
      </div>

      {/* 📁 STEP 3: SUBJECT SELECTOR */}
      <div className="space-y-1.5">
        <label className="block text-[11px] font-mono font-bold text-zinc-400 uppercase tracking-wider">Select Subject</label>
        <select
          value={activeFilters.subject}
          onChange={(e) => onUpdateFilters({ ...activeFilters, subject: e.target.value, chapterId: '' })}
          className="w-full border border-zinc-200 p-2.5 rounded-xl bg-zinc-50/50 text-sm font-semibold text-zinc-800 focus:outline-none focus:border-zinc-400"
        >
          <option value="Physics">⚡ Physics</option>
          <option value="Chemistry">🧪 Chemistry</option>
          <option value="Mathematics">📐 Mathematics</option>
          {activeFilters.preparationLevel === 'FOUNDATION' && <option value="Biology">🧬 Biology</option>}
        </select>
      </div>

      {/* 📖 STEP 4: CHAPTER SELECTION DROPDOWN */}
      <div className="space-y-1.5">
        <label className="block text-[11px] font-mono font-bold text-zinc-400 uppercase tracking-wider">Select Chapter Node</label>
        <select
          value={activeFilters.chapterId}
          onChange={(e) => onUpdateFilters({ ...activeFilters, chapterId: e.target.value })}
          className="w-full border border-zinc-200 p-2.5 rounded-xl bg-zinc-50/50 text-sm font-semibold text-zinc-800 focus:outline-none focus:border-zinc-400"
        >
          <option value="">-- Choose Active Syllabus Topic --</option>
          {filteredChaptersList.map((ch) => (
            <option key={ch.id} value={ch.id}>{ch.title}</option>
          ))}
        </select>
      </div>

      {/* ⚙️ STEP 5: SUB-TRACK EXAM PREP VARIETY */}
      <div className="space-y-1.5">
        <label className="block text-[11px] font-mono font-bold text-zinc-400 uppercase tracking-wider">Exam Sub-Track</label>
        <select
          value={activeFilters.trackType}
          onChange={(e) => onUpdateFilters({ ...activeFilters, trackType: e.target.value })}
          className="w-full border border-zinc-200 p-2.5 rounded-xl bg-zinc-50/50 text-sm font-semibold text-zinc-800 focus:outline-none focus:border-zinc-400"
        >
          {activeFilters.preparationLevel === 'FOUNDATION' ? (
            <>
              <option value="CONCEPTUAL_QUIZ">Conceptual Quizzes (No Calculus)</option>
              <option value="CALCULATION_APPLICATION">Calculation Applications</option>
              <option value="FUTURE_TECH_LAB">Future Tech Project Labs</option>
            </>
          ) : (
            <>
              <option value="JEE_MAIN_DRILL">JEE Main Practice Drills</option>
              <option value="JEE_ADVANCED_CHALLENGE">JEE Advanced Challenges</option>
              <option value="JEE_MOCK_TEST">📝 Full-Pattern JEE Mock Test</option>
            </>
          )}
        </select>
      </div>

      {/* 🚀 GENERATE BUTTON */}
      <div className="pt-2">
        <button
          type="button"
          onClick={() => {
            clearActiveToast();
            onGenerate();
          }}
          disabled={!activeFilters.chapterId && activeFilters.trackType !== 'JEE_MOCK_TEST'}
          className={`w-full font-bold py-3 px-5 rounded-xl text-xs transition shadow-sm tracking-wide text-white uppercase ${
            activeFilters.chapterId || activeFilters.trackType === 'JEE_MOCK_TEST'
              ? "bg-zinc-900 hover:bg-zinc-800 cursor-pointer" 
              : "bg-zinc-300 cursor-not-allowed select-none"
          }`}
        >
          {activeFilters.chapterId || activeFilters.trackType === 'JEE_MOCK_TEST' ? "🚀 Generate Worksheet" : "Select a Chapter First"}
        </button>
      </div>
    </div>
  );
}
